import java.util.function.*;

public class BuiltInFunctionalDemo {
    public static void main(String[] args) {
        // Function / BiFunction
        Function<String, Integer> length = String::length;
        System.out.println(length.apply("Ala ma kota")); // 11

        // Predicate / BiPredicate
        Predicate<String> isBlank = String::isBlank;
        System.out.println(isBlank.test("   ")); // true

        // Supplier
        Supplier<Double> randomValue = Math::random;
        System.out.println(randomValue.get()); // 0.0-1.0

        // Consumer
        Consumer<String> printUpper = s -> System.out.println(s.toUpperCase());
        printUpper.accept("java"); // JAVA

        // UnaryOperator / BinaryOperator
        UnaryOperator<Integer> negate = x -> -x;
        BinaryOperator<Integer> multiply = (a, b) -> a * b;
        System.out.println(negate.apply(9) + ", " + multiply.apply(6, 7)); // -9, 42

        // Kompozycja
        Function<Integer, Integer> addTen = x -> x + 10;
        Function<Integer, Integer> square = x -> x * x;
        System.out.println(addTen.andThen(square).apply(2)); // (2+10)^2 = 144
        System.out.println(addTen.compose(square).apply(2)); // 2^2+10 = 14

        Predicate<Integer> isPositive = x -> x > 0;
        Predicate<Integer> isEven = x -> x % 2 == 0;
        System.out.println(isPositive.and(isEven).test(4)); // true

        // Specjalizacje prymitywne
        IntPredicate isEvenInt = x -> x % 2 == 0;
        IntUnaryOperator doubleInt = x -> x * 2;
        ToIntFunction<String> parseLength = String::length;
        System.out.println(isEvenInt.test(8) + " " + doubleInt.applyAsInt(21)
                + " " + parseLength.applyAsInt("Java")); // true 42 4
    }
}
