class CachedSupplier<T> implements Supplier<T> {
    private final Supplier<T> delegate;
    private T value;
    private boolean computed = false;

    CachedSupplier(Supplier<T> delegate) { this.delegate = delegate; }

    public T get() {
        if (!computed) {
            System.out.println("licze...");
            value = delegate.get();
            computed = true;
        }
        return value;
    }
}

